use anyhow::{bail, Result}; use tokio::io::{AsyncRead,AsyncReadExt,AsyncWrite,AsyncWriteExt}; use tokio::time::{timeout,Duration};
pub async fn RequestConfig<C:AsyncRead+AsyncWrite+Unpin>(conn:&mut C,localPort:&str,deviceID:&str,password:&str)->Result<Option<String>>{conn.write_all(format!("GETCONF:{localPort}|{deviceID}|{password}").as_bytes()).await?;let mut b=[0;4096];let n=timeout(Duration::from_secs(15),conn.read(&mut b)).await??;let r=String::from_utf8_lossy(&b[..n]).into_owned();if r=="NOCONF"{return Ok(None)}if let Some(reason)=r.strip_prefix("DENIED:"){let x=match reason{"wrong_password"=>"FATAL_AUTH: неверный пароль подключения","expired"=>"FATAL_AUTH: срок действия пароля истёк","device_mismatch"=>"FATAL_AUTH: пароль привязан к другому устройству",_=>"FATAL_AUTH: доступ запрещён"};bail!("{x}")}Ok(Some(r))}
